                        <p style="text-align:justify;">NIRM celebrated <strong>77th Independence Day </strong> at NIRM HO, Bengaluru and NIRM RO, KGF. <strong>Dr. H S Venkatesh, Director </strong> , hoisted the National Flag at Bengaluru office and Mr. A Rajan Babu, Officer-in-Charge at KGF Office and addressed the gathering. On this occasion, the Director wished all the employees and made them realize their responsibilities. He said that all the employees should give their best in execution of their duties and help for the growth of the institute as well as development of the country. SWF of NIRM distributed sweets on the occasion.
