                        <h2 id="splcmp23" class="block-head" style="margin-top:3%"> <strong> Special Campaign 2.0  </strong> </h2>

                        <p style="text-align:justify;">National Institute of Rock Mechanics organized the <strong> “Special Campaign 2.0” </strong> for eco-friendly initiatives and cleaning/hygienic activities in and around Head Office Bengaluru since October 2022. Officers and employees participated in this campaign. The main aim of the campaign is to the collection of biodegradable waste/paper waste products etc. and their proper use. During this occasion, cleaning, collection of tree biodegradable waste and plantation were the main activities. All collected tree biodegradable waste was safely decomposed.
                        </p>

                        <p style="text-align:justify;"> The following activities were done during the <strong> “Special Campaign 2.0” </strong>: </p>

                        <br>


                        <ul class="list prim list-ok" style="font-size:14px;">
                            <li> Clean and green office compound with special attention to biodegradable waste.</li>
                            <li> Collection and utilization of tree biodegradable waste (tea leaf/ tree leaf).</li>
                            <li> Collection of useless cartoon boxes and segregation for safe disposal.</li>
                            <li> Utilization of Solar light. </li>
                            <li> Herbal plantation in the campus area.</li>
                            <li> Keeping photographic records of all activities through still photography.</li>

                        </ul>


                        <h2 id="yoga23" class="block-head" style="margin-top:3%"> <strong> विशेष अभियान 2.0 </strong> </h2>

                        <p style="text-align:justify;">राष्ट्रीय शिला यांत्रिकी संस्थान ने अक्टूबर 2022 से प्रधान कार्यालय बेंगलुरु और उसके आसपास पर्यावरण-अनुकूल पहल और सफाई/स्वच्छता गतिविधियों के लिए <strong>"विशेष अभियान 2.0" </strong> का आयोजन किया। अधिकारियों और कर्मचारियों ने इस अभियान में भाग लिया। अभियान का मुख्य उद्देश्य बायोडिग्रेडेबल अपशिष्ट/कागज अपशिष्ट उत्पादों आदि का संग्रह करना और उसका उचित उपयोग करना है। इस अवसर पर सफाई, वृक्ष बायोडिग्रेडेबल कचरे का संग्रहण और वृक्षारोपण मुख्य गतिविधियाँ रहीं। सभी एकत्रित वृक्ष बायोडिग्रेडेबल कचरे को सुरक्षित रूप से विघटित कर दिया गया।
                        </p>

                        <p style="text-align:justify;">   "विशेष अभियान 2.0" के दौरान निम्नलिखित गतिविधियाँ की गईं: : </p>

                        <br>


                        <ul class="list prim list-ok" style="font-size:14px;">
                            <li> बायोडिग्रेडेबल कचरे पर विशेष ध्यान देने के साथ स्वच्छ और हरा-भरा कार्यालय परिसर।</li>
                            <li> बायोडिग्रेडेबल कचरे (चाय की पत्ती/पेड़ की पत्ती) का संग्रहण और उपयोग।.</li>
                            <li> सुरक्षित निपटान के लिए बेकार कार्टून बक्सों का संग्रह और पृथक्करण।</li>
                            <li> सौर प्रकाश का उपयोग। </li>
                            <li> परिसर क्षेत्र में हर्बल वृक्षारोपण।</li>
                            <li> स्थिर फोटोग्राफी के माध्यम से सभी गतिविधियों का फोटोग्राफिक रिकॉर्ड रखना।</li>

                        </ul>

