                        <h2 id="mmd23" class="block-head" style="margin-top:3%"> <strong> Meri Maati Mera Desh  </strong> </h2>

                        <p style="text-align:justify;">Meri Maati Mera Desh campaign is envisaged as a culminating event of Azadi Ka Amrit Mahotsav. It involves paying tribute to the “Veers” who have made the supreme sacrifice for the country, by conducting ceremonies at various levels.
                        </p>
                        <br>
                        <p style="text-align:justify;">National Institute of Rock Mechanics also celebrated <strong> “Meri Mati Mera Desh” </strong> on 14 August at the Head Office, Bengaluru, and on 15 August at the Registered Office, Kolar Gold Fields. On this occasion <strong> Panch Pran Pledge </strong> was taken by Employees and photographs/selfies of the event were uploaded on www.merimaatimeradesh.gov.in.   </p>


                        <h2 id="yoga23" class="block-head" style="margin-top:3%"> <strong> मेरी माटी मेरा देश  </strong> </h2>

                            <p style="text-align:justify;">मेरी माटी मेरा देश अभियान की परिकल्पना आज़ादी का अमृत महोत्सव के समापन कार्यक्रम के रूप में की गई है। इसमें विभिन्न स्तरों पर समारोह आयोजित करके देश के लिए सर्वोच्च बलिदान देने वाले "वीरों" को श्रद्धांजलि देना शामिल है।
                            </p>
                            <br>
                            <p style="text-align:justify;">राष्ट्रीय शिला यांत्रिकी संस्थान ने भी 14 अगस्त को प्रधान कार्यालय, बेंगलुरु में और 15 अगस्त को पंजीकृत कार्यालय, कोलार गोल्ड फील्ड्स में <strong> “मेरी माटी मेरा देश” </strong> मनाया। इस अवसर पर कर्मचारियों द्वारा  <strong> पंच प्राण प्रतिज्ञा  </strong> ली गई और कार्यक्रम की तस्वीरें/सेल्फी www.merimaatimeradesh.gov.in पर अपलोड की गईं।  </p>

