                            <h2 id="yoga23" class="block-head" style="margin-top:3%"> <strong> 9th अंतर्राष्ट्रीय योग दिवस </strong> </h2>

                        <center>

                            <picture>
                                <source type="image/webp" srcset="assets/yoga/yd-23-01.webp">
                                <source type="image/png" srcset="assets/yoga/yd-23-01.png">
                                <img src="assets/yoga1.png" alt="9th अंतर्राष्ट्रीय योग दिवस ">
                            </source></source></picture>

                        </center>


                        <p style="text-align:justify;">After a long day at work, study, household chores or social interactions, tensions get accumulated at various levels of the body, mind and emotions. Yogic relaxation includes techniques from the yogic tradition that help remove these knots from their root, and create a state of inner harmony. The practices not only help to release the day and bring freshness into the evening, but also enable one to face the next day with energy and enthusiasm. Practised over a period of time, they bring about a transformation in one’s attitude towards life.
                        </p>
                        <br>

                        <h2 id="yoga22" class="block-head" style="margin-top:3%"> <strong> Celebration of 9th International Day of Yoga on 21st June 2023  </strong> </h2>

                        <p style="text-align:justify;"> “I am so stressed.” How many times have we heard that statement, whether from our own mouth or someone else’s? The cause may be attributed to work, colleagues, family, finances, interactions (or the lack of them), a long to-do list, life events, or something else. But the common factor in them all: the trigger takes the body-mind unit to the distress zone. Yoga looks at the root causes of stress and not merely on the external symptoms. By systematically following the practices: </p>

                        <br>


                        <ul class="list prim list-ok" style="font-size:14px;">
                            <li> At the physical level we release the tension built up in the muscles and organs and guide the various body systems to function harmoniously.</li>
                            <li> At the mental level, we learn to disconnect from the external stimuli, relax the brain activity, understand our inner chatter, and improve its content.</li>
                            <li> At the emotional level, we release the negative emotions and consciously create positive emotions.</li>
                            <li> At the spiritual level, we discover our inner anchor </li>
                            <li> In addition, by adopting a yogic lifestyle with regularity and moderation in food, sleep and other habits, many anxieties simply drop off over a period of time</li>
                            <li> Gradually, we discover our happy, peaceful, harmonious self that is able to laugh at all that stressed us out once upon a time. And we sleep in peace each night.</li>

                        </ul>

                        <p style="text-align:justify;"> During Yoga session we learned various practices of hatha yoga and raja yoga, including short yoga nidra and meditation, that are particularly helpful in creating relaxation and peace, and releasing stress at all levels.</p>

                        <p style="text-align:justify;"> At the initiative of Honourable Prime Minister Shri Narendra Modi, the United Nations General Assembly took a historic decision in 2014 to declare 21st June as the International Day of Yoga (IDY). In continuation of the tradition of participating in the worldwide programme on International Day of Yoga, NIRM celebrated 9th IDY-2023 by conducting Yoga Session in the NIRM office premises. The yoga session was organised on 21-06-2023, from 9:30 am to 10:45 am. The session was coordinated by NIRM Scientists Dr. DS Rawat and Nodal Officer Dr. Prasnna Jain with the participation of all the Scientists and Staff of NIRM. </p>

                        <p style="text-align:justify;"> The theme of this year is <strong> “Yoga for Vasudhaiva Kutumbakam”.</strong> The domestic tagline for IDY’ 2023 is <strong>“Har Aangan Yog” </strong> being propagated to bring Yoga to every household at the grassroot level.  </p>


                        <p style="text-align:justify;"> Yoga Day observed at NIRM, RO, KGF.  A talk on International Yoga Day was delivered by the Principal Scientist followed by a physical yoga exercise done by all present staff. At Bengaluru, the Yoga Session was conducted by the local Yoga exponent Shri Sn Devarshi, Yoga teacher from Atma Darshan Yogashram, Bengaluru. Yoga Guru also delivered a short speech on the benefits of yoga and urged all the employees to make yoga a part of lifestyle and try to be always happy in present moments with determination. She emphasized that yoga will not only help you to keep fit but also help you to maintain a happy, harmonious, and healthy life. Yoga will help you lead a life with a deeper connection to your own body as well as nature and the universe, benefiting in more ways than one by improving your stamina, immunity, strength, flexibility, and focus. When one becomes consistent with yoga one has mastered the art of living, so let’s pledge to take good care of our health and keep our Indian practices going.    </p>

                        <p style="text-align:justify;">
                            The following is the list of aasanas practiced in the Yoga session:
                        </p>

                        <ul class="list prim list-ok" style="font-size:14px;">
                            <li>Padmaasana</li>
                            <li>Prayer in Meditative Posture with Chin Mudra </li>
                            <li>Chanting of Mantras</li>
                            <li>Joint Movements (Ankle, Neck, Shoulders and Knees) </li>
                            <li> Eka padasana</li>
                            <li> Simhagarjanasana / Lion Roaring Pose</li>
                            <li> Shashank Aasan </li>
                            <li> Surya Namaskar</li>
                            <li> Yoga Nidra (short period)</li>
                            <li> Pranayam (Nadisodhan, Bhramri)</li>
                            <li> Closing Prayer in Meditative Posture with Chin Mudra</li>
                        </ul>


                        <p style="" text-align:justify>
                            The interactive session comprised of clarifications and explanations by the Yoga Guru. All the employees participated with full enthusiasm to mark the IDY 2023.The session was so well designed considering the age, working and background. The Yoga Guru gave useful practical tips and suggestions to enable the employees practice at home and as well as at places where they travel for their duties. For IDY 2023 his emphasis was on inner happiness and humanity. This was advised in daily practice of inner tranquil that will ensure smooth and healthy working atmosphere.
                        </p>





                        <p style="text-align:justify;">

                            Following are the photographs of the Yoga Session – IDY2023:
