                        <h2 id="swp22" class="block-head" style="margin-top:3%"> <strong> Swachhata Pakhwada 2022 </strong> </h2>

                        <h3 style="padding-top:2%;"> <b> Preamble: </b></h3>
                        <p style="text-align:justify;">Hon’ble Prime Minister of India had launched the Swachh Bharat Mission on 2nd October 2014. The mission objectives are to eradicate open defecation, efficient management of solid and liquid waste, encourage cost effective and appropriate technologies for ecologically safe and sustainable sanitation, overall cleanliness and to create significant positive impact on gender and promote social inclusion by improving sanitation. The Swachhata Pakhwada was started with a vision to mainstream Swachhata activities across all Ministries / Departments of Govt. of India. The Ministry of Mines (MoM) and the attached, sub-ordinate and autonomous offices under the administrative control of MoM are actively participating in this national mission since its inception. To carry out Swachhata activities in all institutes of MoM, second fortnight of November 2022 (November 16 - 30) is allocated. In this regard, National Institute of Rock Mechanics (NIRM), an autonomous body under MoM has planned several activities during Swachhata Pakhwada-2022 (Table 1.). On the occasion of “Swachh Bharat Mission”, NIRM organized Swachhata Pakhwada 2022 in and around Head Office, Bengaluru and Registered Office, Kolar Gold Fields during 16th to 30th November 2022. As per day-to-day activities of Swachhata Pakhwada 2022, Maximum employees participated in cleaning, competitions and tree plantation etc. at NIRM HO, Bengaluru and NIRM RO, KGF.</p>


                        <p style="text-align:justify;"> <strong>Table 1. Scheduled of day-to-day activities of Swachhata Pakhwada 2022: </strong> </p>
                        <br>

                        <table border="1" width max>
                            <tr>
                                <td><strong> Date/ दिनांक:</strong></td>
                                <td><strong> Details of the activities / गतिविधियों का विवरण </strong></td>
                            </tr>
                            <tr>
                                <td>16.11.2022</td>
                                <td>Swachhata slogans/Essay will be written by employees; Display of “Swachach Bharat /Swachhata Pakhwada 2022 – Nov 16-30, 2022” in all departments</td>
                            </tr>
                            <tr>
                                <td>17.11.2022 &amp;18.11.2022</td>
                                <td>All employee will weed out unwanted file covers/records/papers etc. </td>
                            </tr>
                            <tr>
                                <td>21.11.2022</td>
                                <td>Employees will clean their sitting areas, desktop, printer etc. </td>
                            </tr>
                            <tr>
                                <td>22.11.2022</td>
                                <td>All employees will carry out clean and green office and compound</td>
                            </tr>
                            <tr>
