                        <p style="text-align:justify;">
                            On the beginning day of Swachhata Pakhwada-2022, Swachhata awareness posters/banners were displayed on NIRM’s notice boards at NIRM HO and NIRM RO. All Swachhata activities were captured through still photography.
                        </p>



