                        <h4 style="padding-top:2%;"> <b> Day 2 &amp; 3: </b></h4>




                        <p style="text-align:justify;">
                            The second and third day’s (17.11.2022 &amp;18.11.2022) activities of Swachhata Pakhwada - 2022 was <b>“All employee will weed out unwanted file covers/records/papers etc.”</b>. All employees weed out unwanted records/papers and categorised of various records from their allocated Almiras/tables. On this occasion various types of files covers etc. were rearranged, various reusable files covers were also segregated and rearranged after proper cleaning at NIRM HO and NIRM RO.
                            All the collected waste file covers and papers were disposed or dumped at the allocated marked places by the particular departments.
                            Day’s activities of 17.11.2022 &amp; 18.11.2022 were uploaded on Govt. of India (Ministry of Jal Shakti) website. Capturing of all activities was done through still photography.
                        </p>



