                        <h2 id="vig22" class="block-head" style="margin-top:3%"> <strong> Vigilance Week 2022 </strong> </h2>


                        <p style="text-align:justify;">Vigilance week 2022 was observed at NIRM from 31st October 2022 to 6th November 2022 at both NIRM Head Quarters, Bengaluru and NIRM registered office, Kolar Gold Fields.</p>
                        <p style="text-align:justify;"> The theme for this year’s Vigilance Week was <strong>Corruption free India for a developed Nation </strong> <strong>भ्रष्टाचार मुक्त भारत – विकसित भारत.</strong> </p>
                        <br>

                        <p style="text-align:justify;">
                            Integrity pledge was taken by all employees at NIRM on 31st October 2022 at 11 AM as shown in the following photographs
                        </p>



