                        <p style="text-align:justify;">
                            A Lecture on “Administrative Vigilance and disciplinary proceedings” by Shri. S Ashok Rao, Registrar, Institute for Social and Economic Charge Nagarbhavi, Bengaluru was organised at NIRM HQ on 2nd November 2022. The program was presided over by Director, NIRM and was attended by all the employees at NIRM. The employees at NIRM registered office and scientists at Camp office Bhutan joined the lecture virtually through WebEX. Dr. Sripad R Naik, CVO NIRM explained the importance of vigilance week and welcomed Shri. Ashok Rao and introduced him to the gathering. Shri Rao explained various aspects of administrative vigilance, service matters. He also explained the constitutional and legal provisions. Scientists and Staff actively participated in the interactive session. Dr. H S Venkatesh, Director, NIRM addressed the gathering and appreciated the active participation by all the scientists and staff. Dr. V R Balasubramanyam , HOD, Engineering Siesmology proposed the vote of thanks. The meeting ended with thanks to the chair. Following are some of the photographs of the event.
                        </p>



