                        <h2 id="fitind22" class="block-head" style="margin-top:3%"> <strong> Fit India Freedom Run 2022 </strong> </h2>





                        <p style="text-align:justify;">On the occasion of the “Fit India Freedom Run 3.0,” National Institute of Rock Mechanics organized Fit India Runs/walks at various locations in Bengaluru. During the occasion, a maximum number of employees participated in various events individually or with family members. Fit Freedom India Run were organized for NIRM Employees and for their family members at nearby localities of their residence and group-wise events were conducted four times in a month. 23.10.2022 was especially for the common people and NIRM employees for this event. </p>
                        <p style="text-align:justify;"> Groupwise Fit India Freedom Run/Walks were conducted in four different localities in Bengaluru are Triangular Park near ISRO layout, Uttarahalli Lake Park Uttarahalli, JHBCS park and playground and at NIRM/GSI campus, Outer ring road Bengaluru. </p>
                        <br>

                        <p style="text-align:justify;">
                            The following activities were carried out during a month-long Fit India Freedom Run 3.0:
                        </p>

                        <ul class="list prim list-ok" style="font-size:14px;">
                            <li>Display of “Fit India Freedom Run 3.0 banners” at display boards in the office and at the locations where the events were organized.</li>
                            <li>Fit India Freedom Run/Walks by various groups of employees, families, and children. </li>
                            <li>Participated in Fit India Freedom Runs/Walks by the common people. </li>
                            <li>Distribution of refreshments and fruit juice after each event. </li>
                            <li>Group-wise Fit India Freedom runs were conducted on 02.10.2022, 16.10.2022, 23.10.2022 and 31.10.2022.</li>
                            <li>Minimum 1.0 km to 4.5 km distance were covered by the individual during these events. </li>
                            <li>Uploading of photographs of “Fit India Freedom Run 3.0” on the “http:www.fitindia.gov.in” site. </li>

                        </ul>


                        <h2 id="fitind22" class="block-head" style="margin-top:3%"> <strong> फिट इंडिया फ्रीडम रन 2022 </strong> </h2>





                        <p style="text-align:justify;">"फिट इंडिया फ्रीडम रन 3.0" के अवसर पर, राष्ट्रीय शिला यंत्रिकी संस्थान ने बेंगलुरु में विभिन्न स्थानों पर फिट इंडिया रन / वॉक का आयोजन किया। इस अवसर पर व्यक्तिगत रूप से या परिवार के सदस्यों के साथ विभिन्न आयोजनों में अधिकतम संख्या में कर्मचारियों ने भाग लिया। एनआईआरएम कर्मचारियों और उनके परिवार के सदस्यों के लिए उनके आवास के आस-पास के इलाकों में फिट फ्रीडम इंडिया रन का आयोजन किया गया था और समूह-वार कार्यक्रम एक महीने में चार बार आयोजित किए गए थे। 23.10.2022 इस आयोजन के लिए विशेष रूप से आम लोगों और एनआईआरएम कर्मचारियों के लिए था। </p>
                        <p style="text-align:justify;"> बेंगलुरु में चार अलग-अलग इलाकों में ग्रुपवाइज फिट इंडिया फ्रीडम रन / वॉक आयोजित किए गए थे, इसरो लेआउट के पास त्रिकोणीय पार्क, उत्तरहल्ली लेक पार्क उत्तरहल्ली, जेएचबीसीएस पार्क और खेल का मैदान और एनआईआरएम / जीएसआई परिसर, बाहरी रिंग रोड बेंगलुरु में। </p>
                        <br>

                        <p style="text-align:justify;">
                            एक महीने तक चलने वाले फिट इंडिया फ्रीडम रन 3.0 के दौरान निम्नलिखित गतिविधियां की गईं:
                        </p>

                        <ul class="list prim list-ok" style="font-size:14px;">
                            <li>कार्यालय में डिस्प्ले बोर्ड और उन स्थानों पर जहां कार्यक्रम आयोजित किए गए थे, "फिट इंडिया फ्रीडम रन 3.0 बैनर" का प्रदर्शन।</li>
                            <li>कर्मचारियों, परिवारों और बच्चों के विभिन्न समूहों द्वारा फिट इंडिया फ्रीडम रन/वॉक। </li>
                            <li>आम लोगों द्वारा फिट इंडिया फ्रीडन रन/वॉक में भाग लिया। </li>
                            <li>प्रत्येक आयोजन के बाद जलपान और फलों के रस का वितरण। </li>
                            <li>समूहवार फिट इंडिया फ्रीडम रन 02.10.2022, 16.10.2022, 23.10.2022 और 31.10.2022 को आयोजित किए गए।</li>
                            <li>इन आयोजनों के दौरान व्यक्ति द्वारा न्यूनतम 1.0 किमी से 4.5 किमी की दूरी तय की गई थी।</li>
                            <li>“फिट इंडिया फ्रीडम रन 3.0” के फोटो को “https://fitindia.gov.in” साइट पर अपलोड करना।</li>

                        </ul>




