                        <h2 id="clind22" class="block-head" style="margin-top:3%"> <strong> Clean India Campaign 2022 </strong> </h2>





                        <p style="text-align:justify;">On the occasion of the “Clean India Campaign,” National Institute of Rock Mechanics organized Clean India Drive in and around NIRM Head Office Bengaluru from 1st to 31st October 2022. On this occasion, the approximate collection of waste material is 42 kilograms.</p>
                        <br>

                        <p style="text-align:justify;">
                            The following activities were carried out during Clean India Campaign 2022:
                        </p>

                        <ul class="list prim list-ok" style="font-size:14px;">
                            <li>Collection of single-use plastic from all departments.</li>
                            <li>Collection of waste thermocol sheets. </li>
                            <li>Collection of useless cartoon boxes. </li>
                            <li>Collection of unwanted records/papers. </li>
                            <li>Capturing of all activities through still photography.</li>
                        </ul>


                        <h2 id="clind22" class="block-head" style="margin-top:3%"> <strong> स्वच्छ भारत अभियान 2022</strong> </h2>



                        <p style="text-align:justify;"> "स्वच्छ भारत अभियान" के अवसर पर, राष्ट्रीय शिला यांत्रिकी संस्थान ने 1 से 31 अक्टूबर 2022 तक एनआईआरएम प्रधान कार्यालय बेंगलुरु में और उसके आसपास स्वच्छ भारत अभियान का आयोजन किया। इस अवसर पर, अपशिष्ट सामग्री का अनुमानित संग्रह 42 किलोग्राम है।</p>
                        <br>
                        <p style="text-align:justify;">
                            स्वच्छ भारत अभियान 2022 के दौरान निम्नलिखित गतिविधियां की गईं:
                        </p>

                        <ul class="list prim list-ok" style="font-size:14px;">
                            <li>सभी विभागों से सिंगल यूज प्लास्टिक का संग्रहण।</li>
                            <li>अपशिष्ट थर्मोकोल शीट का संग्रह।</li>
                            <li>बेकार कार्टून बॉक्स का संग्रह। </li>
                            <li>अवांछित अभिलेखों/कागजातों का संग्रह।</li>
                            <li>स्थिर फोटोग्राफी के माध्यम से सभी गतिविधियों को कैप्चर करना।</li>
                        </ul>

