                        <h2 id="hp22" class="block-head" style="margin-top:3%"> <strong> हिंदी-पखवाड़ा –2022 at NIRM </strong> </h2>
                        <center>

                            <picture>
                                <source type="image/webp" srcset="assets/hp22/hp-22-01.webp">
                                <source type="image/png" srcset="assets/hp22/hp-22-01.png">
                                <img src="assets/hp22/hp-22-01.png" alt="Hindi Pakhwada">
                            </source></source></picture>

                        </center>




                        <p style="text-align:justify;">राजभाषा विभाग, गृह मंत्रालय, भारत सरकार से प्राप्त निर्देशों के अनुमोदन के अनुसरण में, एन.आई.आर.एम. मुख्य-कार्यालय, बैंगलोर और पंजीकृत-कार्यालय, के.जी.एफ में राजभाषा हिंदी के प्रगतिशील प्रयोग को बढ़ावा देने के उद्देश्य से विभिन्न कार्यक्रमों के साथ हिंदी पखवाड़े का आयोजन 14 सितंबर से 29 सितंबर, 2022 तक किया गया। “हिंदी दिवस का महत्व” “भारत के राष्ट्रीय चिन्ह और उनका महत्व” विषयों पर निबंध लेखन, “हिंदी दिवस और हिंदी भाषा”, “पर्यावरण एवं प्रकृति” से संबंधित पोस्टर मेकिंग (चित्रांकन), आदर्श वाक्य रचना, एवं कविता पाठ प्रतियोगितायेँ, हिंदी पखवाड़े के दौरान आयोजित की गयी।</p>
                        <br>
                        <p style="text-align:justify;"> एन.आई.आर.एम. निदेशक एवं अध्यक्ष राजभाषा समिति, डॉ. एच. एस. वेंकटेश की अध्यक्षता में दिनांक 14 सितंबर 2022 को हिन्दी-दिवस मनाया गया एवं हिन्दी पखवाड़े का शुभारंभ किया गया, एवं उन्होंने हिन्दी पखवाड़े के आयोजन पर बधाई दी एवं अपना हर्ष व्यक्त किया। 29 सितंबर 2022 को हिंदी-पखवाड़ा समापन और पुरस्कार वितरण समारोह आयोजित किया गया। सभी अधिकारी एवं कर्मचारी इस कार्यक्रम में शामिल हुए। सबसे पहले सुश्री प्रवीणा दास जेनिफर, वरिष्ठ वैज्ञानिक एवं सदस्य राजभाषा समिति ने स्वागत भाषण द्वारा सभी उपस्थित अधिकारियों का स्वागत किया। भगवान गणेश एवं माँ सरस्वती की वंदना के साथ हिन्दी-पखवाड़े के समापन समारोह का आरंभ किया गया। इसके बाद हिंदी गीत "हिंदी हिंदुस्तान के धड़कन है” का प्रसारण किया गया, इस गीत के दौरान पिछले 3-4 वर्षो के हिन्दी पखवाड़ा आयोजन के छायाचित्रों को भी दिखाया गया जिससे पुरानी यादें ताजा हो गयी। इसके पश्चात डॉ प्रसन्न जैन, वरिष्ठ वैज्ञानिक एवं राजभाषा अधिकारी ने हिंदी के महत्व और संस्थान में हिंदी के कार्यान्वयन पर अपने विचार व्यक्त किए। इसके पश्चात हिंदी भाषा के लिए महान व्यक्तियों द्वारा दिए गए उद्धरण श्री शशिनाथ वर्मा द्वारा पढ़े गए। इसके बाद डॉ विकल्प कुमार ने राजभाषा से जुड़े हुए रोचक तथ्यो की जानकारी दी। इसके बाद कविता-पाठ प्रतियोगिता की शुरुआत की गयी, सभी ने बहुत ही रोचक एवं प्रेरणादायक प्रस्तुति दी। कविता-पाठ प्रतियोगिता का संचालन श्री भारत कुमार, वैज्ञानिक एवं सदस्य राजभाषा समिति द्वारा बहुत ही रोचक तरीके से किया गया। विजेताओं का मूल्यांकन “क”,“ख” और “ग” क्षेत्रों के प्रतियोगियों के आधार पर डॉ॰ पी.सी. झा, वरिष्ठ वैज्ञानिक द्वारा किया गया। इसके पश्चात सभी विभागाध्यक्षों ने हिंदी के सम्मान और कार्यान्वयन में अपना विचार व्यक्त किए ताकि अन्य कर्मचारियों को भी हिंदी के उपयोग के लिए प्रेरणा मिले। प्रभारी निदेशक महोदय डॉ. श्रीपाद नाय्क ने अपने भाषण में सांस्कृतिक कार्यक्रमों को सफलतापूर्वक आयोजित करने और बच्चो एवं अधिकारियों द्वारा दी गयी प्रस्तुति कि सराहना करते हुए कहा कि हिंदी भारतीयता की पहचान है। हिंदी भाषा पूरे देश को संचार भाषा के रूप में जोड़ने में महत्वपूर्ण भूमिका निभाती है। हिंदी प्रयोग के अर्थ का विस्तार करते हुए उन्होंने कहा कि हमें संस्थान की प्रगति के साथ-साथ कार्यालय के दैनिक कार्यों में भी हिंदी को अपनाना चाहिए। पुरस्कार वितरण समारोह में प्रभारी निदेशक महोदय द्वारा विभिन्न प्रतियोगिताओं के विजेताओ एवं प्रतिभागियों को पुरस्कार के साथ सम्मानित किये जाने की घोषणा की। समापन समारोह के अंत में सुश्री प्रवीणा दास जेनिफर, सदस्य राजभाषा समिति द्वारा राजभाषा हिंदी के अधिक उपयोग के लिए उपयुक्त वातावरण बनाने के लिए निदेशक महोदय का आभार व्यक्त किया गया। अंत मे सभी के सहयोग एवं उपस्थिति के लिए सबको धन्यवाद प्रेषित किया।</p>
