                        <h2 id="yoga22" class="block-head" style="margin-top:3%"> <strong> अंतर्राष्ट्रीय योग दिवस Celebration of 8th International Day of Yoga on 21st June 2022 at NIRM </strong> </h2>

                        <p style="text-align:justify;"> <strong>योग भारत की प्राचीन परम्परा का एक अमूल्य उपहार है यह दिमाग और शरीर की एकता का प्रतीक है; मनुष्य और प्रकृति के बीच सामंजस्य है </strong>
                        </p>
                        <p style="text-align:justify;">Yoga is an ancient physical, mental, and spiritual practice that originated in India. The word ‘yoga’ derives from Sanskrit and means to join or to unite, symbolizing the union of body and consciousness. This worldwide acceptance of yoga is a matter of pride for our country, as yoga is an integral part of our culture and spiritual heritage
                        </p>
                        <br>
                        <p style="text-align:justify;"> At the initiative of Honourable Prime Minister <strong>Shri Narendra Modi,</strong> the United Nations General Assembly took a historic decision in 2014 to declare 21st June as the <strong>International Day of Yoga (IDY)</strong>. In continuation of the tradition of participating in the worldwide programme on International Day of Yoga, NIRM celebrated IDY-2022 by conducting Yoga Session in the NIRM office premises. The yoga session was organised on 21-06-2022, from 9:30 am to 10:45 am. The session was coordinated by NIRM Scientist and Nodal Officer Dr. Prasnna Jain with the participation of all the Scientists and Staff of NIRM.
                        </p>
                        <p style="text-align:justify;"> At Bengaluru, the Yoga Session was conducted by the local Yoga exponent Shri Sn Devanand, Yoga teacher from Atma Darshan Yogashram, Bengaluru. Yoga Gurus also delivered short speech on the benefits of yoga and urged all the employees to make yoga as a part of day-to-day routine and try to be always happy in present moments with determination. He also told that yoga will not only help you keep fit but also help you lead a better and healthy life. So, many diseases and health conditions can be improved when one practices yoga which consists of various asanas or postures and breathing exercises as well which is called pranayama. It will help you lead a life with a deeper connection to your own body as well as nature and the universe, benefiting in more ways than one by improving your stamina, immunity, strength, flexibility, and focus. When one becomes consistent with yoga one has mastered the art of living, so let’s pledge to take good care of our health and keep our Indian practices going.
                        </p>
                        <br>


                        <p style="text-align:justify;">
                            The following is the list of aasanas practiced in the Yoga session:
                        </p>

                        <ul class="list prim list-ok" style="font-size:14px;">
                            <li>Padmaasana</li>
                            <li>Prayer in Meditative Posture with Chin Mudra </li>
                            <li>Chanting of Mantras</li>
                            <li>Joint Movements (Ankle, Neck, Shoulders and Knees) </li>
                            <li> Eka padasana</li>
                            <li> Hasta bandh Uttanasana</li>
                            <li> Tadasana </li>
                            <li> Tiryak Taadaasana</li>
                            <li> Kati Chakraasana</li>
                            <li> Makarasan</li>
                            <li> Marjariasana (Cat pose) </li>
                            <li> Yoga Nidra (short period)</li>
                            <li> Pranayam (Nadisodhan, Bhramri)</li>
                            <li> Closing Prayer in Meditative Posture with Chin Mudra</li>
                        </ul>

                        <p style="text-align:justify;"> The interactive session comprised of clarifications and explanations by the Yoga Guru. All the employees participated with full enthusiasm to mark the IDY 2022.The session was so well designed considering the age, working and background. The Yoga Guru gave useful practical tips and suggestions to enable the employees practice at home and as well as at places where they travel for their duties. For IDY 2022 his emphasis was on inner happiness and humanity. This was advised in daily practice of inner tranquil that will ensure smooth and healthy working atmosphere.</p>

                        <p style="text-align:justify;">

                            Following are the photographs of the Yoga Session – IDY2022:
