                        <h3 id="jraja" class="block-head" style="margin-top:3%">Superannuation of Shri J. Raja, Section Officer </h3>

                        <p style="text-align:justify;">
                            NIRM bid farewell to <strong> Shri J Raja, Section officer, Administration </strong> who retired from NIRM service on 30.04.2022 on attaining the age of superannuation after more than 29 years of his sincere and dedicated services. His farewell felicitation was conducted on April 29, 2022 NIRM HO, Bengaluru. His family members, friends and all the NIRM employees attended the felicitation programme. The felicitation programme was organized by the Staff Welfare Fund of NIRM. The programme was presided over by Dr. H.S. Venkatesh, Director, NIRM. Dr. Divyalakshmi K.S., Treasurer SWF welcomed the gathering and Dr A.K. Naithani, President SWF read the citation of Shri J. Raja's service. Dr. Vikalp Kumar, Member SWF made the vote of thanks for this event.
                        </p>
                        <br>

                        <p style="text-align:justify;">
                            He worked in the Administration, Finance &amp; Accounts Departments, Technical Services Division, Material Testing Laboratory etc. For the last few years, he was also looking after the maintenance of vehicles, office buildings, managing security guards, housekeeping personnel etc. at NIRM Registered Office, KGF.
                        </p>
                        <div class="padd-top-25 center" style="    padding-top: 25px;">

