                    <div class="cell-12 ">
                        <h3 id="Wd2022" class="block-head" style="margin-top:3%">Swachchata Action Plan- 2021-22 </h3>

                        <p style="text-align:justify;">
                            As per the direction from the Ministry of Jal Shakti, Govt. of India (Ref: F. no. S/10//2016-0/o Secy (DWS), National Institute of Rock Mechanics celebrated the Hygiene/cleanliness program under Swachchata Action Plan-2021-22 during March 2022, at Govt. Higher Primary School, Kumarswamy Layout, Bengaluru, Government High School, Kysamballi and St.Theresa's Girls High School, Robertsonpet in Kolar Gold Fields. On the occasion of SAP-2021-22 at Bengaluru, the Principal, all teachers of the School, the President, SWF, the Controller of Administration, and Scientists of NIRM, were present. NIRM provided steel plates to ensure hygiene to serve mid-day meals and distributed hankeys to all students. Scientists shared information about the benefits of hygiene with students. During the celebration of SAP 2021-22 at KGF, both Principals, all teachers of Government High School, Kysamballi, St.Theresa's Girls High School, Robertsonpet, the Officer-in-charge, Registered Office, NIRM, KGF, and employees were present. Awareness programs and sanitisation at both schools’ premises were conducted for the benefit of students and teachers. On this occasion, the Officer-in-charge and employees shared various information about the benefits of hygiene with students. NIRM provided all necessary cleaning items like liquid soap, soap, phenyl, bleaching powder, harpic, brooms, dust bins, hand towels, Dettol etc. to all schools to keep them clean and hygienic. </p>
                        <br>

                        <p style="text-align:justify;">
                            Following activities were done during the Swachchata Action Plan 2021-22:
                        </p>

                        <ul class="list prim list-ok" style="font-size:14px;">
                            <li>Displaying of a Swachchata slogan through posters</li>
                            <li>Distribution of necessary cleaning items for all schools </li>
                            <li>Distribution of hygiene kits to students</li>
                            <li>Scientists shared information about the benefits of hygiene with students </li>

                        </ul>

                    </div>
                </div>
            </div>

            <div class="row">
                <div class="container">

                    <div class="cell-12 ">
                        <h3 id="Wd2022" class="block-head" style="margin-top:3%">स्वच्छ कार्य योजना 2021-22 </h3>

                        <p style="text-align:justify;">
                            जल शक्ति मंत्रालय, भारत सरकार के निर्देशानुसार (संदर्भ: एफ. संख्या एस/10//2016-0/ओ सचिव (डीडब्ल्यूएस), राष्ट्रीय शिला यांत्रिकी संस्थान ने स्वच्छता कार्य योजना- (SAP) 2021-22 के तहत स्वच्छता कार्यक्रम, सरकारी उच्च प्राथमिक विद्यालय कुमारस्वामी लेआउट, बेंगलुरु, गवर्नमेंट हाई स्कूल, क्यासमबली और सेंट थेरेसा गर्ल्स हाई स्कूल, रॉबर्टसनपेट, कोलार गोल्ड फील्ड्स में मार्च 2022 के दौरान मनाया। बेंगलुरु में SAP-2021-22 के अवसर पर, स्कूल के प्रधानाचार्य, स्कूल के सभी शिक्षक, अध्यक्ष, SWF, नियंत्रक प्रशासन और वैज्ञानिक, राष्ट्रीय शिला यांत्रिकी संस्थान उपस्थित थे। राष्ट्रीय शिला यांत्रिकी संस्थान ने मध्याह्न भोजन परोसने के लिए स्वच्छता सुनिश्चित करने के लिए स्टील प्लेट्स प्रदान की और सभी छात्रों को हैंकी वितरित किए। वैज्ञानिकों ने छात्रों के साथ स्वच्छता के लाभों के बारे में जानकारी साझा की। केजीएफ में स्वच्छता कार्य योजना (SAP) 2021-22 के उत्सव के दौरान, दोनों प्रधानाध्यापक, सरकारी हाई स्कूल, क्यासमबली, सेंट थेरेसा गर्ल्स हाई स्कूल, रॉबर्टसनपेट के सभी शिक्षक और प्रभारी अधिकारी, पंजीकृत कार्यालय, राष्ट्रीय शिला यांत्रिकी संस्थान, केजीएफ और कर्मचारी मौजूद थे। जागरूकता कार्यक्रम और दोनों स्कूलों परिसर की साफ़ -सफाई छात्रों और शिक्षकों के लाभ के लिए आयोजित किया गया। इस अवसर पर प्रभारी अधिकारी एवं कर्मचारियों ने विद्यार्थियों के साथ स्वच्छता से होने वाले लाभों की जानकारी साझा की। राष्ट्रीय शिला यांत्रिकी संस्थान ने सभी स्कूलों को साफ और स्वच्छ रखने के लिए सभी आवश्यक सफाई सामग्री जैसे तरल साबुन, साबुन, फिनाइल, ब्लीचिंग पाउडर, हार्पिक, झाड़ू, कूड़ेदान, हाथ तौलिये, डेटॉल तरल आदि प्रदान किए। </p>
                        <br>

                        <p style="text-align:justify;">
                            स्वच्छता कार्य योजना 2021-22 के दौरान निम्नलिखित गतिविधियां की गईं:
                        </p>

                        <ul class="list prim list-ok" style="font-size:14px;">
                            <li>पोस्टरों के माध्यम से स्वच्छता नारे का प्रदर्शन</li>
                            <li>सभी विद्यालयों में आवश्यक सफाई सामग्री का वितरण </li>
                            <li>छात्रों को स्वच्छता किट का वितरण</li>
                            <li>वैज्ञानिकों ने छात्रों के साथ स्वच्छता के लाभों के बारे में जानकारी साझा की</li>

                        </ul>

                    </div>
                </div>
            </div>

            <div class="row">
                <div class="container">
                    <div class="cell-12 fx">
                        <div class="padd-top-25 center" style="    padding-top: 25px;">

                            <picture>
