            <div class="row">
                <div class="container">

                    <div class="cell-12 ">
                        <h3 id="Wd2022" class="block-head" style="margin-top:3%">International Women's Day 2022 </h3>

                        <p style="text-align:justify;">
                            National Institute of Rock Mechanics celebrated International Women’s Day 2022 as a part of Azadi ka Amrut Mahotsava, on 8th March 2022 (Tuesday) at NIRM HO, Bengaluru .
                            On this occasion, the Internal Committee (IC - Women) of the Institute invited all the Scientists, Head of Departments, and staff of the Institute to attend and actively participate in the program organized to celebrate the occasion. The IC members and women employees of the Institute took active initiative in organizing the various activities of the program. The activities organized were as follows: </p>
                        <ul class="list prim list-ok" style="font-size:14px;">
                            <li>Invited talk on the topic “Women’s achievements, initiatives for eliminating gender based discrimination and violence for bringing about a perceptible change and positive shift towards real empowerment of women” by Ms. Piyali Bagchi, a Senior legal professional and a POSH Consultant </li>
                            <li>Discussions on the women issues</li>
                        </ul>

                        <br>

                        <p style="text-align:justify;">
                            Employees at both NIRM HO, Bengaluru and NIRM RO, KGF actively participated in the program and made the event successful.
                        </p>
                    </div>
                </div>
            </div>

