                    <div class="cell-12 ">
                        <h3 id="com-eight" class="block-head" style="margin-top:3%">Commemoration of eighth anniversary of Sexual Harassment of women at workplace, (Prevention, Prohibition and Redressal) Act 2013, at NIRM </h3>
                        <p style="text-align:justify;">National Institute of Rock Mechanics conducted an awareness program for all the employees of NIRM on 9th December 2021 to commemorate the eighth anniversary of notification of said landmark legislation.
                        </p>
                        <p style="text-align:justify;">The awareness session was conducted by inviting <strong> Dr. Meena K Jain, Ex-Chairperson of CWC,Bengaluru Urban </strong> and a Certified POSH Trainer and Consultant, to deliver a lecture on the topic "The Sexual Harassment of Women at Workplace (Prevention, Prohibition and Redressal) Act, 2013" followed by discussions </p>
                        <p>
                            <strong> Some of the snapshots of the above lecture are displayed below: </strong>

                        </p>
