                        </h3>
                        <p style="text-align:justify;">NIRM celebrated <b>75th Independence Day </b> at NIRM HO, Bengaluru and at NIRM RO, KGF. <b>Dr. H S Venkatesh, Director, NIRM </b> hoisted the National Flag at the Head office, Bengaluru and addressed the gathering. <b> Mr. A Rajan Babu, Officer In-charge </b> at registered Office, KGF hoisted the national flag and addressed the gathering. Mr. AY Bharth Kumar, Scientist and Member of Staff Welfare Fund briefed about the Azadi ka Amrutha Mahotsav. SWF of NIRM distributed sweet on the occasion.
