                    <div class="cell-12 contact-form fx" data-animate="fadeInLeft" id="contact">
                        <h2 id="yoga21" class="block-head" style="margin-top:3%"> 7th International Day of Yoga Celebration - IDY 2021 “Yoga for Wellness” NIRM, Bengaluru and KGF </h2>
                        <p style="text-align:justify;"> YOGA is a physical, mental, and spiritual practice that is originated from India which describes the complete way of life. YOGA is not all about exercise but to discover the sense and identify yourself. The word YOGA has been derived from Sanskrit which means join or unite or else union of the body. International Day of Yoga is a global event celebrated on every 21st of June. This year the whole world celebrated the 7th International Day of Yoga. As this year theme declared by the Ministry of AYUSH India was <strong color="blue">“Yoga for Wellness”</strong>
                        </p>
                        <br>
                        <p style="text-align:justify;"> This year’s theme shares a message that during COVID-19 people must stay home with family and should do yoga regularly for wellness as it is shown that yoga can be one of the best therapeutic during a pandemic. In continuation of the tradition of participating in the worldwide programme on International Day of Yoga, NIRM Scientists and Staff of NIRM HO (Bengaluru) and NIRM RO (KGF) also celebrated IDY-2021 by performing Yoga Session in their respective homes with family. Most of the Scientist and staff are regular in practicing Yoga, on the occasion of IDY-2021 with help of common yoga protocol (CYP) videos and booklet designed by Ministry of AYUSH, practice of asanas (Physical postures), pranayama (breathing exercise) and dhyana (meditation) were performed. Dr. H. S. Venkatesh, Director NIRM has performed yoga along with family was inspirational to all. During Lockdown Dr. Prasnna Jain, Scientist and Nodal Officer IDY-2021, NIRM motivated and taught Yoga in his apartment by maintaining social distancing.
                        </p>
                        <br>
                        <p style="text-align:justify;"> <strong color="blue">Picture gallery of Performing yoga with theme of “Yoga for wellness” by NIRM employees. </strong>
                        </p>
