                        <h3 id="Wd2021" class="block-head" style="margin-top:3%">International Women's Day 2021 </h3>

                        <p style="text-align:justify;">
                            National Institute of Rock Mechanics celebrated International Women’s Day 2021 on 8th March 2021 (Monday) at NIRM HO, Bengaluru. On this occasion, the Internal Committee (IC - Women) of the Institute invited all the Scientists, Head of Departments, Administrative heads and staff of the Institute to attend and actively participate in the programs organized to celebrate the occasion. The IC members and women employees of the Institute took active initiative in organizing the various activities of the program. The activities organized were as follows:
                        </p>
                        <ul class="list prim list-ok" style="font-size:14px;">
                            <li>Invited talk on ‘Today’s Women and the importance of Role play’ by Ms. Meena Jain (Ex-Chairperson of Child Welfare Committee, Bengaluru Urban)</li>
                            <li>Activities and games related to ‘Importance of Role play’</li>
                            <li>Discussions </li>
                        </ul>

                        <br>

                        <p style="text-align:justify;">
                            In view of the Covid-19 situation, following safety measures the Director, Head of Departments and Women employees of the Institute only gathered in the Conference room. A Webex meeting link was sent to all the employees to participate in the program.  
                        </p>
                        <p style="text-align:justify;">
                            Employees at both NIRM HO, Bengaluru and NIRM RO, KGF actively participated in the program and made the event successful.
                        </p>


