                        <h3 id="Uday" class="block-head" style="margin-top:3%">Superannuation of Shri S. Udayakumar </h3>

                        <p style="text-align:justify;">
                            NIRM bid farewell to <b>Shri S. Udayakumar, Scientist II </b>, Centre for Testing Services who retired from NIRM service on 31.01.2021 on attaining the age of superannuation after more than <b>39</b> years of his sincere and dedicated services. His farewell felicitation was conducted on <b>January 29, 2021 </b> through webinar and in NIRM RO, KGF. His family members and all the NIRM employees attended the felicitation programme. Felicitation programme was organized by the Staff Welfare Fund of NIRM. The programme was presided over by <b>Dr. H.S. Venkatesh, Director, NIRM.</b>
                        </p>
                        <br>

                        <p style="text-align:justify;">
                            His experience was useful in various projects undertaken by NIRM related to Laboratory geotechnical investigations on rock samples for various mining, civil and hydroelectric power projects. He is a well-trained person to perform and conduct laboratory as per various National &amp; International Standards on rock samples using MTS Servo Hydraulic testing machine and also performs calibration for all the machines at MTL and RFM Labs.
                        </p>

