                        <h3 id="IntYoga" class="block-head" style="margin-top:3%">International Yoga Day at NIRM "Yoga at Home and Yoga with Family"</h3>
                        <p style="text-align:justify;"> NIRM Scientist Dr.Prasnna Jain participated in <span style="color:#0000FF"> <b>My Life My Yoga </b></span> Video Blogging Competition organised by the ministry of AYUSH. </p>
                        <div class="cell-12 fx">
                            Your browser does not support the &lt;video&gt; tag.
                                <source src="assets/Video/Nirm-2.m4v"></source>
                                
                        </div>

                        <br>
                        <br>

                        <h4 style="margin-top:3%"> <span style="color:#420A7F"> <b> 6th International Day of Yoga Celebration - IDY 2020 "Yoga at Home and Yoga with Family" NIRM, Bengaluru and KGF </b> </span> </h4>

                        <div>
                            <p style="text-align:justify;"> YOGA is a physical, mental, and spiritual practice that is originated from India which describes the complete way of life. YOGA is not all about exercise but to discover the sense and identify yourself. The word YOGA has been derived from Sanskrit which means join or unite or else union of the body. International Day of Yoga is a global event celebrated on every 21st of June. This year the whole world celebrated the 6th International Day of Yoga. As this year theme declared by the Ministry of AYUSH India was <span style="color:#0000FF"> <b>Yoga at Home and Yoga with Family</b> </span>.
                            </p>
                            <br>
                            <p style="text-align:justify;"> This year’s theme shares a message that during COVID-19 people must stay home with family and should do yoga regularly as it is shown that yoga can be one of the best therapeutic during a pandemic. In continuation of the tradition of participating in the worldwide programme on International Day of Yoga, NIRM Scientists and Staff of NIRM HO (Bengaluru) and NIRM RO (KGF) also celebrated IDY-2020 by performing Yoga Session in their respective homes with family. Most of the Scientist and staff are regular in practicing Yoga, on the occasion of IDY-2020 with help of common yoga protocol (CYP) videos and booklet designed by Ministry of AYUSH, practice of asanas (Physical postures), pranayama (breathing exercise) and dhyana (meditation) were performed. Dr. H. S. Venkatesh, Director NIRM has performed yoga along with family including his son studying in USA with online assistance was inspirational to all. NIRM employee has also participated in <span style="color:#0000FF"> <b>My Life My Yoga </b></span> Video Blogging Competition. During Lockdown Dr. Prasnna Jain, Scientist and Nodal Officer IDY-2020, NIRM motivated and taught Yoga in his apartment by maintaining social distancing.
                            </p>
                            <br>
                            <p style="text-align:justify;">Picture gallery of Performing yoga with theme of <span style="color:#0000FF"> <b>Yoga at Home and Yoga with Family</b> </span> by NIRM employees.</p>



