                        <h3 id="Ambedkar" class="block-head" style="margin-top:3%"> Ambedkar Jayanti 2020 Celebration
                        </h3>
                        <p style="text-align:justify;"> NIRM celebrated 129th birth anniversary of Dr.Babasaheb Ambedkar on 14th April amid lockdown due to Covid-19 Crisis. At the Head office few scientits garlanded the portrait of Bharat Ratna Dr. Bhimrao Ramji Ambedkar and remembered his immense contribution in drafting the Indian Constitution and the society as a whole.
                            at Registered office, KGF, Mr.Rajan Babu,OIC garlanded the portrait of Dr. B R Ambedkar and addressed the few personnel present on the occassion. During the gathering, social distancing norms and other lockdown guidelines were strictly followed.
