                        <h3 id="Covid" class="block-head" style="margin-top:3%">Awareness on COVID-19 Virus
                        </h3>
                        <p style="text-align:justify;">With regard to the spread of deadly COVID 19 virus Dr. Divyalakshmi KS, Scientist &amp; Nodal officer on 11-3-2020 has conducted an awareness program. During the interaction she explained about how the virus is spreading from a sick person to the healthy person and what precautions are to be taken by individuals. She also demonstrated the usage of various types of preventive mask and proper disposal of it. She also proposed some precautionary measures need to be adopted by NIRM HO &amp; RO for the safety of the employees within the office environment. The program was chaired by Dr. H.S. Venkatesh, Director NIRM, and he also gave instructions to follow the necessary measure to stop the possibility of spreading of COVID 19 virus at NIRM HO &amp; RO.
                            <br>
                        </p>
