                            <h3 class="block-head" style="margin-top:3%">23rd Peer Review Committee Meeting held at NIRM, Bengaluru</h3>

                            <p style="text-align:justify;">23rd Peer Review Committee meeting of NIRM was held at NIRM HQ on 24th February 2020 under the chairmanship of <b>Prof. B. B. Dhar, Former Director CIMFR</b>. Dr. H.S. Venkatesh, Director, NIRM welcomed chairman and members of Peer Review Committee. The committee reviewed the technical activity of all departments of NIRM and appreciated the activities of NIRM in serving the nation in the diverse areas of Rock Mechanics and Rock Engineering. <br> </p>

                        </div>
                    </div>

                    <div class="row">
                        <div class="cell-6">
                            <p>The committee members who attended the meeting are:</p>
                            <ul class="list prim list-ok" style="font-size:14px;">
                                <li class="fx animated undefined">Prof. B. B. Dhar, Former Director CIMFR, Chairman</li>
                                <li class="fx animated undefined">Shri. A Sundaramoorthy, Director General (Retd) GSI, Member</li>
                                <li class="fx animated undefined">Prof. VMSR Murthy, Professor, IIT/ISM Dhanbad, Member</li>
                                <li class="fx animated undefined">Shri. G Vijaya Kumar, DDG, DGMS, Southern Region, Member</li>
                                <li class="fx animated undefined">Prof. N R Thote, Professor, VNIT, Nagpur, Member</li>
                                <li class="fx animated undefined">Shri. N Radhakrishna, Representing G M R &amp; D, SCCL, Member</li>
                                <li class="fx animated undefined">Shri. Jitendra Kumar Singh, Chief Scientist, CSIR-CIMFR, Member</li>
                                <li class="fx animated undefined">Dr.H.S.Venkatesh, Director NIRM, Member</li>
                            </ul>


                        </div>
