                        <div class="cell-12 contact-form fx" data-animate="fadeInLeft" id="contact">
                            <h3 class="block-head" style="margin-top:3%"><b> 71st Republic Day Celebration</b>
                            </h3>
                            <p style="text-align:justify;"> NIRM celebrated 71st Republic Day at NIRM HO, Bengaluru, and NIRM RO, KGF. Dr. P. C. Jha, Scientist -V and HOD, Engineering Geophysics Department, hoisted the National Flag at Bengaluru office, and Officer-in-Charge, Mr. A. Rajan Babu hoisted the National Flag at KGF Office. Both the Officers addressed the gathering at Bengaluru and KGF respectively. Dr. D. S. Rawat, Scientist and Treasurer of Staff Welfare Fund (SWF) briefed about the National Flag. SWF, NIRM distributed sweet on the occasion.</p>
                            
                        </div>

                        <div class="cell-6 fx">
                            <div class="padd-top-25 center" style="    padding-top: 25px;">
