                <div class="container">
                    <div class="row">
                        <div class="cell-12" data-animate="fadeInLeft" id="contact">
                            <h3 class="block-head" style="margin-top:3%">22nd Peer Review Committee Meeting held at NIRM, Bengaluru</h3>

                            <p style="text-align:justify;">22nd Peer Review Committee meeting of NIRM was held at NIRM HQ on 17th December 2019 under the chairmanship of <b>Prof. B. B. Dhar, Former Director CIMFR</b>. Dr. H.S. Venkatesh, Director, NIRM welcomed chairman and members of Peer Review Committee. The committee reviewed the technical activity of all departments of NIRM and appreciated the activities of NIRM in serving the nation in the diverse areas of Rock Mechanics and Rock Engineering. <br> </p>

                        </div>
                    </div>

