                        <div class="cell-12">
                            <h3 class="block-head" style="margin-top:3%">Farewell function of Shri.Sivakumar Cherukuri</h3>

                            <p style="text-align:justify;">NIRM bid farewell to <b>Sri Sivakumar Cherukuri,Scientist-V and HOD Engineering Seismology Department</b>, who retired from NIRM service on 29.11.2019 on attaining the age of superannuation after more than 30 years of his sincere and dedicated services. His farewell felicitation was conducted on November 29, 2019, in NIRM HO, Bengaluru. His family members and NIRM employees attended the felicitation programme. Felicitation programme was organized by the Staff Welfare Fund of NIRM.
                                <br>His vast experience was useful in various projects undertaken by NIRM related to development and application of the microseismic technology for the stability monitoring of underground structures in Hydroelectric tunnels, storage caverns, coal mines, hard rock mines and slopes in India and abroad.
                                <br>
                            </p>


                            <center> <img src="assets/news/csk1.jpg"></center>
                            <h3 style="padding-top:1%;text-align:center;"> <b>NIRM Scientists and Staff with Shri.Sivakumar Cherukuri and his family </b></h3>

                            <br>
                            <br>
                        </div>
                    </div>
                </div>


                <div class="row">
                    <div class="container">
                        <div class="cell-12 ">
                            <h3 class="block-head" style="margin-top:3%">NIRM celebrates Constitution Day</h3>
                            <p style="text-align:justify;"> <b>Constitution Day of India </b> is celebrated on 26 November every year. In 2019, it marks the 70th anniversary of the adoption of the Constitution and raises awareness about the Indian Constitution.26 November has its own importance in the history of independent India because on this day in 1949, the Constitution of India was adopted and it came in to effect on 26 January, 1950. Therefore, marking the dawn of a new era. To acknowledge the contribution of the framers of the Constitution and to aggravate the people regarding the prominent values, 26 November is celebrated as the 'Constitution Day'.At NIRM HQ, the celbration started with reading the 'preamble'of the Constitution by all the scientists and staff. Dr. H.S. Venkatesh, Director NIRM addressed the gathering and highlighted the importance of Constitution. </p>
                            <p style="text-align:justify;"> </p> At NIRM RO Shri.Rajan Babu, Principal Scientist addressed the scientists and staff and highlighted the importance of constitution and this was followed by reading the 'preamble'of the Constitution by all the scientists and staff.
                        </div>
                    </div>
                </div>
