                <div class="row">
                    <div class="container">
                        <div class="cell-12 ">
                            <h3 class="block-head" style="margin-top:3%">INDOROCK-2019 Conference Lecture by Dr. H.S. Venkatesh, Director, NIRM </h3>
                            <p style="text-align:justify;"> <b>Dr. H.S. Venkatesh, Director NIRM </b> delivered conference lecture on <b>"Rock blasting and sustainable development" in 8th Indian Rock Conference INDOROCK-2019</b> organized by Indian Society of Rock Mechanics and Tunnelling Technology (ISRMTT) in association with Central Soil and Material Research Station (CSMRS) and WAPCOS Ltd at India International Centre, New Delhi from 4th to 5th November 2019. This paper is published in proceedings edited by Mr. Hari Dev and Dr. Rajbal Singh. The Conference was inaugurated by His Excellence Hans Jacob Frydenlund, The Ambassador of Norway.</p>


                        </div>
                    </div>
                </div>
                <div class="row">
                    <div class="container">
                        <div class="cell-6 fx">
                            <div class="padd-top-25 center" style="    padding-top: 25px;">
                                <img alt="" src="assets/indorock-1.jpg">
                                <h4 style="padding-top:2%;"> <b>Dr.H S Venkatesh, Director, NIRM at INDOROCK-2019</b></h4>
                            </div>
                        </div>

                        <div class="cell-6 fx">
                            <div class="padd-top-25 center" style="    padding-top: 25px;">
                                <img alt="" src="assets/indorock-2.jpg">
                                <h4 style="padding-top:2%;"> <b>Dr.H S Venkatesh, Director, NIRM delivering Conference Lecture at INDOROCK-2019</b></h4>
                            </div>
                        </div>
                    </div>
                </div>

                <div class="row">
                    <div class="container">

                        <div class="cell-12 ">
                            <h4 class="block-head" style="margin-top:3%">ISRMTT Best Paper Award </h4>

                            <p style="text-align:justify;">NIRM Research Paper entitled <b>“Engineering geological investigations of deep open surge pool area of lift irrigation scheme – a case study from Telangana State”</b> authored by <b>A.K. Naithani, D.S. Rawat, L.G. Singh and Prasnna Jain </b>, published in <b>Journal of Rock Mechanics &amp; Tunnelling Technology (JRMTT)</b> is awarded with best paper award by Indian Society of Rock Mechanics and Tunnelling Technology (ISRMTT) under the category of <b>‘Case history of tunnelling and foundations on rock’</b>. Award was received by <b> Dr. A.K. Naithani </b> on 4th November 2019 during the inaugural session of INDOROCK-2019 held at New Delhi and given by <b>His Excellence Hans Jacob Frydenlund</b>, The Ambassador of Norway.</p>
                            <div class="padd-top-25 center" style="    padding-top: 25px;">
                                <img alt="" src="assets/indorock-3.jpg" width="640" height="380">
                                <h4 style="padding-top:2%;"> <b>Dr.A K Naithani, Scientist, NIRM receiving Best Paper Award at INDOROCK-2019</b></h4>
                            </div>

                        </div>
                    </div>
                </div>





                <div class="row">
                    <div class="container">
                        <div class="cell-12 ">
                            <h3 class="block-head" style="margin-top:3%">Academic programmes at NIRM </h3>
                            <p style="text-align:justify;"> <b>NIRM </b> is recognised as Research Centre to offer Ph.D. and M.Sc. (Engg) by research under the aegis of <b>Visvesvaraya Technological University (VTU), Belagavi </b> vide notification No. VTU/Aca-Res-cen./A4/2018-19/1633/35 dated 25th May 2018. This has been done under section (41) of VTU Act, 1994. Initial notification was granted for the year 2018-19 only and subsequently this is being renewed and kept in force till date.</p>

                            <p style="text-align:justify;"> Since NIRM caters to applied research by offering its services for providing solutions to the industry for a wide range of rock engineering problems, we would like to start the Research Programme leading to <b>Ph.D. in Rock Mechanics </b> for the employees of our partner industries. They will be enrolled as part-time research scholars and adhere to the rules, regulations and norms of the VTU for external (part-time) research scholars.</p>

                            <p style="text-align:justify;"> In this connection two-member delegation from NIRM comprising <b>Dr P C Jha, Scientist &amp; Head (Engineering Geophysics) and Dean (Academic and Research)</b> and <b>Dr D S Subrahmanyam, Scientist &amp; Head (Geotechnical Engineering) and Dean (Admin)</b> met the <b>Vice Chancellor of VTU, Prof.Karisiddappa, </b> on 11th October 2019 and apprised him of our intention to start this course. After detailed discussions, the VC agreed and consented to go ahead for the release of Press Advertisement seeking applications for the part-time research programme. The delegation also met <b>Dr. A. S. Deshpande, Registrar, VTU </b> and apprised him of our intention. He too extended full cooperation and support from VTU.</p>

                            <p style="text-align:justify;"> Accordingly, we are going to release advertisement in December 2019 seeking admissions to part-time research programme leading to Ph D in Rock Mechanics from 2020-21 year onwards. This will be open to executives/employees belonging to Mining and Civil Engineering discipline as well as to candidates with Post Graduate programme in Geology/Applied Geology/ Applied Geophysics with five years experience in the area of rock mechanics. We would like to enrol inter-disciplinary streams associated with rock engineering related research too as per the norms of VTU.</p>

                            <p style="text-align:left;"><b>Dr. DS Subrahmanyam </b> </p>
                            <p style="text-align:left;"> <b>Dean (Administration)</b> </p>

                        </div>
                    </div>
                </div>

