                            </h3>
                            <p style="text-align:justify;"> <b> Dr.H.S.Venkatesh, Director, NIRM </b> delivered <b>1st Prof.A.K.Ghose Memorial lecture </b> at <b>National Seminar on Mining and Processing of Raw Materials for Stell-Cement &amp; Power and Annual Awards Function of 2019, organised by IME &amp; AKS University </b> held on 21-22nd September, 2019 at Hosapete, Karnataka. Dr. Venkatesh delivered lecture on "Sustainable Development -A Way Forward through Blasting Technology. The seminar was attended by many eminent persons from the Mining Industry and Academia.<br>
