                            <div class="padd-top-25 center" style="    padding-top: 25px;">
                                <img alt="" src="assets/73-Ind-09.jpg">
                                <h3 style="padding-top:2%;"> <b>Illuminated NIRM RO Building on the occassion of 73rd Independence day</b></h3>
                            </div>
                        </div>

                    </div>
                </div>

                <div class="row">
                    <div class="container">

                        <div class="cell-12 contact-form fx" data-animate="fadeInLeft" id="contact">
                            <h3 class="block-head" style="margin-top:3%"><b> Inter-Ministerial Conference on Future Strategies for NIRM</b>
                            </h3>
                            <p style="text-align:justify;"> <b>NIRM along with Ministry of Mines, Govt. of India organised an Inter-ministerial conference on 26th April 2019 at The Ashok Hotel at New Delhi. Shri. Anil G Mukim, IAS, Secretary, Ministry of Mines, Govt. of India chaired the Conference. Dr. K. Rajeswara Rao, IAS, Additional Secretary, Ministry of Mines and Controller General, Indian Bureau of Mines, Govt. of India graced the occasion. Shri. Dorji P Phuntshok, Director (Projects), Druk Green Power Corporation Ltd, Bhutan was Guest of Honour during the conference. Shri Alok Chandra, Economic Adviser, Ministry of Mines graced the occasion. Dr. H S Venkatesh, Director, NIRM welcomed all and briefed about various activities of NIRM. More than 50 officers from various ministries of Govt. of India, invited guests from Industry and other prestigious organisations like DRDO, CWC, NIDM, NPCIL, NHPC Ltd., HZL, Northern Railways participated and interacted and shared their previous experiences with NIRM and also highlighted their future requirements. </b> </p>

                            <p> <b>Shri. Anil G Mukim, IAS, Secretary, Ministry of Mines, Govt. of India appreciated the progress and achievement made by NIRM in its 30 years of existence and assured complete support from Ministry of Mines in its future endeavours. Additional Secretary, Ministry of Mines stressed the need for expansion of NIRM’s activities in International Arena and urged other ministries to take note of NIRM’s exhaustive portfolio in rock mechanics and rock engineering. Shri. Dorji P Phuntshok narrated his long-term association with NIRM and acknowledged the contribution of dedicated team of NIRM scientists in Bhutan Projects. </b></p>


                            <p> <b>The following Industry Partners and Invited guests spoke at the Conference. </b></p>
                            <ul class="list prim list-ok" style="font-size:14px;">
                                <b>
                                    <li class="fx animated undefined">Shri. Balraj Joshi, Chairman and Managing Director, NHPC Ltd.</li>
                                    <li class="fx animated undefined">Shri. Laxman Shekawat, Chief Operating Officer, Hindustan Zinc Ltd.</li>
                                    <li class="fx animated undefined">Shri. S.M.Ingole, Associate Director, NPCIL. </li>
                                    <li class="fx animated undefined">Shri. T K Sivarajan, CE Designs (E&amp;NE), Central Water Commission</li>
                                    <li class="fx animated undefined">Shri. Desh Ratan Gupta, Chief Engineer/ Const./ Survey, Northern Railways</li>
                                </b>
                            </ul>
                            <p> <b>Dr. K. Rajeswara Rao, IAS, Additional Secretary, Ministry of Mines and Controller General, Indian Bureau of Mines, Govt. of India conducted interactive session with the ministry officers and industry partners. He expressed that NIRM will achieve greater heights under the dynamic leadership of Dr. H S Venkatesh and asked the scientists to continue to maintain the high standard and high quality in their scientific work. </b></p>


