                            <h3 class="block-head" style="margin-top:3%"><b> Conference with Industry Partners on Future Strategies</b>
                            </h3>
                            <p style="text-align:justify;"> <b>NIRM organised a "Conference with Industry Partners on Future Strategies" on 18th Feb 2019 at Taj Yeshwantpur, Bengaluru under the chairmanship of Dr. K. Rajeswara Rao, IAS, Additional Secretary, Ministry of Mines and Controller General, Indian Bureau of Mines, Govt. of India. Shri. Dorji P Phuntshok, Joint Managing Director, Punatsangchhu HEP-II, Bhutan was Guest of Honour during the conference. Shri Alok Chandra, Economic Adviser and Shri Amit Saran, Director of Ministry of Mines graced the occasion. More than 25 industry partners participated and interacted. Dr. H S Venkatesh, Director, NIRM welcomed all and briefed about various activities of NIRM. Industry partners shared their previous experiences with NIRM and also highlighted their future requirements. Shri. Dorji P Phuntshok narrated his long term association with NIRM and continued support of NIRM for Projects in Bhutan. Additional Secretary, Ministry of Mines expressed satisfaction over feedback from the industry and also assured complete support from Ministry of Mines for NIRM's future endeavours. Organizing Secretary, Dr. Sripad R Naik, HOD, NMD presented the vote of thanks. The event was sponsored by JSW Ltd. </b> </p>
