                <div class="row">
                    <div class="container">

                        <div class="cell-12 contact-form fx" data-animate="fadeInLeft" id="contact">
                            <h3 class="block-head" style="margin-top:3%"><b> Visit of Secretary to Govt. of India, Ministry of Mines to NIRM HO at Bangalore</b>
                            </h3>
                            <p style="text-align:justify;"> <b> Shri.Anil G Mukim, Secretary to Govt. of India, Ministry of Mines, visited our Head Office at Bengaluru on 17th December 2018. He was welcomed by Dr H S Venkatesh, Director and felicitated by Mr Rajan Babu, Scientist-F and Liaison Officer, SC/ST Cell of NIRM. Mr Mukim was accompanied by Mr Alok Chandra, Economic Advisor of Ministry of Mines and Ms.Farida M Naik, Director, Ministry of Mines. During this visit he reviewed the activities of NIRM. Mr Santosh Sharma, CMD, HCL and Dr. Ranjit Rath, CMD, MECL too joined this review meeting in which all HoDs of Scientific departments were present.
                            </b></p>

                            <p style="text-align:justify;"> <b> Dr. H S Venkatesh, Director, NIRM presented the activities of the Institute. He explained that even with a small work-force, NIRM apart from its parent obligation of supporting the mining industry, has left an indelible foot-print in almost all hydroelectric projects of the country. He explained that off-late the Institute has diversified its activities to support nuclear and thermal power, infrastructure sector and other sectors of societal importance. During the course of his presentation, Dr. Venkatesh highlighted the technical expertise of NIRM vis-à-vis scope of expansion of this Institute to scale new heights if supported by the Government. He presented a roadmap of the Institute in which possibility of developing the institute into three verticals – academics, skill development and forays into international collaboration was explained. </b></p>

                            <p style="text-align:justify;"> Secretary (mines) visited the scientific departments where respective HoDs explained the work being done by the Institute in diversified fields. Secretary (Mines) expressed his appreciation for the work being carried out by this small and well compacted institute. He assured full support and cooperation of government in development of the Institute as per planned roadmap and suggested to hasten up the target elements of the roadmap.
                            </p>

                        </div>
