                            <h3 class="block-head" style="margin-top:3%"><b> Dr. H S Venkatesh, Delivers Keynote Lecture at National seminar on Rock Blasting Techniques - Challenges and Opportunities</b>
                            </h3>
                            <p style="text-align:justify;"> During the National seminar on <b>Rock Blasting Techniques - Challenges and Opportunities </b> at Central Institute of Mining and Fuel Research (CIMFR), Dhanbad on 23-24 November, 2018. <b> Professor D. P. Singh </b> was honored for his
                                Life time contribution to Mining and Rock Engineering. As part of the events, Prof. Singh was honored by various dignitaries and Director, NIRM too felicitated Prof. Singh on behalf of NIRM.
                            </p>

                            <p> <b> Dr. H S Venkatesh, Director, NIRM</b> delivered a keynote lecture on <b>"Sustainability of Blasting"</b>. <b>Dr.P.K. Singh, Director, CIMFR </b> honored <b>Dr. H S Venkatesh</b> for having taken over as Director, NIRM.
                            </p>

                        </div>
