                <div class="container">


                    <div class="cell-12">
                        <h3 class="block-head" style="margin-top:3%">Farewell function of Mr. N. Selvaraj
                        </h3>
                        <p style="text-align:justify;">NIRM bid farewell to Sri N. Selvaraj, Lab Assistant-III, who retired from NIRM service on 30.09.2018 on attaining the age of superannuation after more than 28 years of his sincere and dedicated services. His farewell felicitation was conducted on September 28, 2018, in NIRM RO, KGF. His family members and NIRM employees attended the felicitation programme. Felicitation programme was organized by the Staff Welfare Fund of NIRM.
                            <br>His vast experience was useful in various projects undertaken by NIRM related to coal, metal mining, slope stability studies in open cast mining and hydro-electric projects in Himachal Pradesh and Bhutan. He was the recipient of “NIRM Best Staff Award” for the year of 2011.

                            <br>
                        </p>


                        <center> <img src="assets/news/news4.jpg"></center>
                        <h3 style="padding-top:1%;text-align:center;"> <b>NIRM Scientists and Staff with Mr. N. Selvaraj </b></h3>

                        <br>
                        <br>
                    </div>
                </div>

                <div class="padd-top-50">
                    <div class="container">
                        <div class="row">
                            <div class="cell-12" data-animate="fadeInLeft" id="contact">
                                <h3 class="block-head" style="margin-top:3%">21st Peer Review Committee Meeting held at NIRM
                                </h3>
                                <p style="text-align:justify;">21st Peer Review Committee meeting of NIRM was held at Bangalore on 28th August 2018 under the chairmanship of <b>Prof. B. B. Dhar, Former Director CIMFR</b>. Dr. H.S. Venkatesh, Director, NIRM welcomed chairman and members of Peer Review Committee. The committee reviewed the technical activity of all departments of NIRM and appreciated the activities of NIRM in serving the nation in the diverse areas of Rock Mechanics and Rock Engineering. <br> </p>

                            </div>
                        </div>

                        <div class="row">
                            <div class="cell-6">
                                <p>The committee members who attended the meeting are:</p>
                                <ul class="list prim list-ok" style="font-size:14px;">
                                    <li class="fx animated undefined">Prof. B. B. Dhar, Former Director CIMFR, Chairman</li>
                                    <li class="fx animated undefined">Prof. V.R Sastry, Professor, NITK, Surtathkal, Alternate Chairman and Member</li>
                                    <li class="fx animated undefined">Shri A Sundaramoorthy, Director General (Retd) GSI, Member</li>
