                    <div class="container">
                        <div class="row">
                            <div class="cell-12 contact-form fx" data-animate="fadeInLeft" id="contact">
                                <h3 class="block-head" style="margin-top:3%">Praveena Das J and Shruthi B S attend a 2-day workshop on “The Sexual Harassment of Women at workplace (Prevention, Prohibition and Redressal) Act, 2013” on July 20th &amp; 21st , 2018
                                </h3>
                                <p style="text-align:justify;"><b>Mrs. Praveena Das Jennifer, Scientist-II</b> and <b>Mrs. B.S. Shruthi, Office Assistant-I </b> attended the 44th 2-day Workshop on <b>“The Sexual Harassment of Women at workplace (Prevention, Prohibition and Redressal) Act, 2013” </b> on <b>July 20th &amp; 21st , 2018</b> at The Gateway Hotel, Wakad road, Pune. The Institute of Public Administration (IPA) is an empanelled Institute under the Ministry of Women and Child Development, Government of India, to impart training under Sexual Harassment of Women at Workplace (Prevention, Prohibition and Redressal)Act, 2013. The IPA conducts this training on regular basis with view to give proper rendition of the Acts and Rules related to Sexual harassment at workplace .
                                    Under the Sexual Harassment at Workplace Act, 2013, it is compulsory for any organisation with 10 or more employees to set up an Internal Complaints Committee (ICC) for addressing complaints of sexual harassment. The Workshop mainly emphasized on setting up of an ICC, training the members of the ICC to conduct domestic inquiry flawlessly so that the establishment does not lose the Sexual Harassment case on technical ground in the court of law and to apprise the Employer of the provisions of the Act and Rules made thereunder.
                                    <br>
                                </p>
                            </div>
                        </div>
