                                <h3 class="block-head" style="margin-top:3%">Farewell Function of Mr. Jakkarasakuppa Vishwanatha Sastry &amp; Mr. Syed Asghar
                                </h3>
                                <p style="text-align:justify;">NIRM bid farewell to<b> Sri Jakkarasakuppa Vishwanatha Sastry, Section Officer (Internal Audit)</b>, who retired from NIRM service on 31.07.2018 (Tuesday) on attaining the age of superannuation after more than 24 years of his sincere and dedicated services. His farewell felicitation was conducted on July 30, 2018 in NIRM HO, Bengaluru. His family members and NIRM employees attended felicitation programme. Felicitation programme was organized by Staff Welfare Fund of NIRM. His knowledge and vast experience related to finance was useful in regulating the funds received by the NIRM. He worked zealously for the all-round development of the Administration of the Institute.
                                    <br>
                                </p>
                                <p style="text-align:justify;">NIRM bid farewell to <b> Mr. Syed Asghar, Technician-IV </b>, who retired from NIRM service on 31.07.2018 (Tuesday) on attaining the age of superannuation after more than 36 years of his sincere and dedicated services. His farewell felicitation was conducted on July 31, 2018 in NIRM RO, KGF. His family members and NIRM employees attended felicitation programme. Felicitation programme was organized by Staff Welfare Fund of NIRM. His vast experience was useful in various projects undertaken by NIRM related to mines, hydel, tunneling projects, underground crude storage schemes.
                                    <br>
                                </p>

                            </div>
                        </div>
                    </div>


