                                <h3 class="block-head" style="margin-top:3%">COA attends Training Programme on “Parliamentary Procedures”
                                </h3>
                                <p style="text-align:justify;">Dr. Sandeep Nelliat, Scientist-III and Controller of Administration attended a 3 days Customised Training Programme on “Parliamentary Procedures” at the Parliamentary &amp; Administrative Research Institute (PARI), New Delhi. The intensive training was undertaken to delve in to the details of parliamentary and administrative procedures in India and to understand the relationship between the Executive and the Legislature.
                                    <br>
                                </p><p style="text-align:justify;">PARI has been on the forefront for bringing out certain capacity building courses on Parliamentary procedure which enable the stakeholders to deal with the Parliament efficiently. The capacity building courses are tailor-made for officers of the ministries/department/PSUs/Autonomous Bodies.
                            </p></div>
