                            <div class="cell-12 contact-form fx" data-animate="fadeInLeft" id="contact">
                                <h3 class="block-head" style="margin-top:3%">MoU between GSI and NIRM
                                </h3>
                                <p style="text-align:justify;">Geological Survey of India and National Institute of Rock Mechanics, Bangalore signed a Memorandum of Understanding (MoU) on 16th July, 2018 for providing additional office space to NIRM, Bangalore within the premises of GSI at the existing GSI Chemical and Ore-Dressing Laboratory (CODL), Eshwarnagar, Bangalore as per the directive of Ministry of Mines.
                                    <br>
                                </p><p style="text-align:justify;">The agreement is for leasing of the office space measuring 4112.472 sq. ft. area of CODL, GSI for a period of 20 years or till the time of vacation of occupant (NIRM) whichever is earlier on long term lease basis as permissible in the Government rules. However, the MoU may be extended or terminated by mutual consent.
                                    <br>
                                </p><p style="text-align:justify;">The MoU has been signed by Dr. Dinesh Gupta, Director General, Geological Survey of India on behalf of GSI and Dr. H.S. Venkatesh, Director, NIRM on behalf of National Institute of Rock Mechanics, Bangalore.
                                    <br>
                                </p>
                            </div>


                            <div class="cell-6 fx">
                                <div class="padd-top-25 center" style="    padding-top: 25px;">
                                    <img alt="" src="assets/gsi-nirm-1.jpg">
                                    <h3 style="padding-top:2%;"> <b>Exchange of signed MoU between Dr. Dinesh Gupta, Director General, GSI &amp; Dr. H. S. Venkatesh, Director, NIRM </b></h3>
                                </div>
                            </div>
                            <div class="cell-6 fx">
                                <div class="padd-top-25 center" style="    padding-top: 25px;">
