                                    <h3 style="padding-top:2%;"> <b> Presence of the Director General, GSI with Director, NIRM and other Dignitaries of GSI &amp; NIRM during signing Ceremony of MOU </b></h3>
                                </div>
                            </div>
                        </div>
                    </div>





